select.if:
SELECT classification.id 'product_class.id', classification.classification_name 'product_class.name', product.quantity, product.net_weight, product.gross_weight FROM (SELECT structure_class_id, SUM( quantity ) quantity, IFNULL(SUM( quantity * net_weight ),0) net_weight, IFNULL(SUM( quantity * gross_weight ),0) gross_weight FROM tech_artifact
structure_class_id IS NOT NULL AND bool_delete_enum=0
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
AND area_id=#{areaId}
GROUP BY structure_class_id)product LEFT JOIN sys_structure_classification classification ON classification .id=product.structure_class_id ORDER BY product.quantity DESC

SELECT config.id 'product_class.id', config.`name` 'product_class.name', product.quantity, product.net_weight FROM (SELECT assemble_config_id, SUM( quantity ) quantity, SUM( quantity * net_weight ) net_weight FROM tech_assemble
bool_delete_enum=0
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
AND area_id=#{areaId}
GROUP BY assemble_config_id)product LEFT JOIN sys_assemble_config config ON config .id=product.assemble_config_id ORDER BY product.quantity DESC
